# -*- coding: utf-8 -*-
exec(open('lib4.py',encoding='utf-8').read())
c='p7';B='CSDL 3'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 3','SQL: TRUY VẤN<br>VÀ NHÓM DỮ LIỆU','SELECT, WHERE, ORDER BY, LIMIT, LIKE, IN, BETWEEN; hàm tổng hợp; GROUP BY, HAVING; thứ tự thực hiện.',['SELECT','WHERE','GROUP BY','HAVING','COUNT/AVG']))
S.append(goals(c,B,['Viết truy vấn <b>SELECT … FROM … WHERE</b>.','Dùng <b>ORDER BY, LIMIT, DISTINCT, LIKE, IN, BETWEEN, IS NULL</b>.','Dùng hàm tổng hợp <b>COUNT, SUM, AVG, MIN, MAX</b>.','Dùng <b>GROUP BY</b> và <b>HAVING</b>; phân biệt WHERE và HAVING.','Nắm <b>thứ tự thực hiện</b> câu truy vấn.'],['SELECT cơ bản','Lọc và sắp xếp','Hàm tổng hợp','GROUP BY, HAVING','Thứ tự thực hiện, HSG']))
S.append(S2(c,B+' · 0','Dữ liệu dùng trong bài',RES(OUT(SQLRUN(SETUP,'SELECT * FROM hocsinh'),22),'Bảng HOCSINH'),RES(OUT(SQLRUN(SETUP,'SELECT * FROM lop'),22),'Bảng LOP')+KEY('Hai bảng này dùng cho <b>mọi ví dụ</b> trong bài. <b>HOCSINH.lop</b> là khoá ngoài tới <b>LOP.malop</b>.')))
S.append(SQ(c,B+' · 1','SELECT: chọn cột','SELECT hoten, diemtb FROM hocsinh',KEY('<b>SELECT</b> cột <b>FROM</b> bảng. Dấu <b>*</b> là mọi cột. Có thể đổi tên cột bằng <b>AS</b>.'),24))
S.append(SQ(c,B+' · 1','Cột tính toán và bí danh (AS)','SELECT hoten, diemtb * 10 AS diem100 FROM hocsinh',KEY('Biểu thức trong SELECT: <code>diemtb * 10</code>; <b>AS</b> đặt <b>bí danh</b> cho cột kết quả.'),23))
S.append(SQ(c,B+' · 1','DISTINCT: loại trùng','SELECT DISTINCT lop FROM hocsinh',KEY('<b>DISTINCT</b> bỏ các dòng kết quả <b>trùng nhau</b>: 6 học sinh nhưng chỉ có 3 lớp.'),24))
S.append(SQ(c,B+' · 2','WHERE: lọc dòng','SELECT hoten, diemtb\nFROM hocsinh\nWHERE diemtb >= 8 AND lop = \'12A\'',KEY('<b>WHERE</b> giữ lại các dòng thoả điều kiện. Ghép bằng <b>AND, OR, NOT</b>. Xâu đặt trong <b>nháy đơn</b>.'),22))
S.append(TB(c,B+' · 2','Toán tử trong điều kiện',['Toán tử','Ý nghĩa','Ví dụ'],[['<code>=, &lt;&gt;, &lt;, &gt;, &lt;=, &gt;=</code>','so sánh (khác: <code>&lt;&gt;</code> hoặc <code>!=</code>)','<code>diemtb &lt;&gt; 7</code>'],['<code>BETWEEN a AND b</code>','trong đoạn [a, b] (gồm hai đầu)','<code>diemtb BETWEEN 7 AND 8</code>'],['<code>IN (…)</code>','thuộc danh sách','<code>lop IN (\'12A\',\'12C\')</code>'],['<code>LIKE</code>','khớp mẫu (<code>%</code> nhiều kí tự, <code>_</code> một kí tự)','<code>hoten LIKE \'B%\'</code>'],['<code>IS NULL</code>','giá trị rỗng','<code>diemtb IS NULL</code>']],mono=1,note=WARN('<b>BETWEEN</b> gồm cả hai đầu mút. So sánh với NULL phải dùng <b>IS NULL</b>.')))
S.append(SQ(c,B+' · 2','BETWEEN, IN, LIKE','SELECT hoten, lop, diemtb FROM hocsinh\nWHERE diemtb BETWEEN 7 AND 8.5\n  AND lop IN (\'12A\',\'12C\')\n  AND hoten LIKE \'%a\'',KEY('LIKE <code>\'%a\'</code>: tên <b>kết thúc bằng a</b>. Ở đây chỉ Ha thoả cả ba điều kiện.'),20))
S.append(SQ(c,B+' · 2','ORDER BY: sắp xếp','SELECT hoten, diemtb FROM hocsinh\nORDER BY diemtb DESC, hoten ASC',KEY('<b>ASC</b> tăng dần (mặc định), <b>DESC</b> giảm dần. Có thể sắp theo <b>nhiều cột</b>: điểm giảm, đồng điểm theo tên.'),22))
S.append(SQ(c,B+' · 2','LIMIT: lấy n dòng đầu','SELECT hoten, diemtb FROM hocsinh\nORDER BY diemtb DESC\nLIMIT 3',KEY('<b>3 học sinh điểm cao nhất</b>: sắp giảm rồi <b>LIMIT 3</b>. (SQL Server dùng <code>TOP 3</code>.)'),24))
S.append(SQ(c,B+' · 3','Hàm tổng hợp trên toàn bảng','SELECT COUNT(*) AS so_hs,\n       ROUND(AVG(diemtb),2) AS tb,\n       MAX(diemtb) AS cao_nhat,\n       MIN(diemtb) AS thap_nhat,\n       SUM(diemtb) AS tong\nFROM hocsinh',KEY('<b>Hàm tổng hợp</b> gộp nhiều dòng thành <b>một giá trị</b>. <b>COUNT(*)</b> đếm dòng; AVG, SUM, MAX, MIN <b>bỏ qua NULL</b>.'),21))
S.append(TB(c,B+' · 3','Các hàm tổng hợp',['Hàm','Ý nghĩa','Chú ý'],[['<code>COUNT(*)</code>','số dòng','đếm cả dòng có NULL'],['<code>COUNT(cột)</code>','số giá trị <b>khác NULL</b>','bỏ NULL'],['<code>COUNT(DISTINCT cột)</code>','số giá trị khác nhau','—'],['<code>SUM, AVG</code>','tổng, trung bình','bỏ NULL'],['<code>MIN, MAX</code>','nhỏ nhất, lớn nhất','dùng được với xâu, ngày']],mono=1,note=KEY('Có hàm tổng hợp trong SELECT mà <b>không có GROUP BY</b> thì kết quả chỉ <b>một dòng</b>.')))
S.append(SQ(c,B+' · 3','Đếm có điều kiện','SELECT COUNT(*) AS nu,\n       ROUND(AVG(diemtb),2) AS tb_nu\nFROM hocsinh\nWHERE gioitinh = \'Nu\'',KEY('<b>WHERE</b> lọc dòng <b>trước</b>, hàm tổng hợp tính <b>sau</b>: 4 học sinh nữ.'),22))
S.append(SQ(c,B+' · 4','GROUP BY: nhóm dữ liệu','SELECT lop, COUNT(*) AS so_hs,\n       ROUND(AVG(diemtb),2) AS tb\nFROM hocsinh\nGROUP BY lop',KEY('<b>GROUP BY lop</b> chia bảng thành các nhóm cùng lớp; hàm tổng hợp tính <b>riêng từng nhóm</b>.')+WARN('Mọi cột trong SELECT <b>không nằm trong hàm tổng hợp</b> phải có trong <b>GROUP BY</b>.'),22))
S.append(S2(c,B+' · 4','Minh hoạ GROUP BY',RES('<svg viewBox="0 0 520 290" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="23" text-anchor="middle"><rect x="10" y="10" width="160" height="270" fill="#E8EAF6" stroke="#283593" stroke-width="3"/><text x="90" y="38" fill="#283593">HOCSINH</text><g fill="#0B2545"><text x="90" y="75">An · 12A</text><text x="90" y="105">Binh · 12A</text><text x="90" y="135">Chi · 12B</text><text x="90" y="165">Dung · 12B</text><text x="90" y="195">Em · 12A</text><text x="90" y="225">Ha · 12C</text></g><path d="M175 145 L215 145 M205 130 L220 145 L205 160" stroke="#C62828" stroke-width="5" fill="none"/><text x="195" y="120" fill="#C62828" font-size="20">nhóm</text><rect x="225" y="10" width="140" height="95" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><text x="295" y="40" fill="#0B2545">12A</text><text x="295" y="70" fill="#0B2545">An, Binh, Em</text><text x="295" y="95" fill="#C62828">n=3</text><rect x="225" y="115" width="140" height="80" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><text x="295" y="145" fill="#0B2545">12B</text><text x="295" y="172" fill="#0B2545">Chi, Dung</text><text x="295" y="190" fill="#C62828">n=2</text><rect x="225" y="205" width="140" height="75" fill="#C5CAE9" stroke="#283593" stroke-width="3"/><text x="295" y="235" fill="#0B2545">12C</text><text x="295" y="258" fill="#0B2545">Ha</text><text x="295" y="276" fill="#C62828">n=1</text><path d="M370 145 L405 145 M395 130 L410 145 L395 160" stroke="#C62828" stroke-width="5" fill="none"/><rect x="415" y="85" width="95" height="120" fill="#FFB300"/><text x="462" y="115" fill="#0B2545" font-size="22">3 dòng</text><text x="462" y="145" fill="#0B2545" font-size="22">kết quả</text><text x="462" y="175" fill="#0B2545" font-size="22">(mỗi nhóm</text><text x="462" y="195" fill="#0B2545" font-size="22">một dòng)</text></g></svg>','Từ 6 dòng thành 3 nhóm'),card('Ý nghĩa',ul(['Sáu bản ghi gộp thành <b>ba nhóm</b>.','Mỗi nhóm cho <b>một dòng</b> kết quả.'],6))))
S.append(SQ(c,B+' · 4','HAVING: lọc nhóm','SELECT lop, COUNT(*) AS so_hs,\n       ROUND(AVG(diemtb),2) AS tb\nFROM hocsinh\nGROUP BY lop\nHAVING COUNT(*) >= 2',KEY('<b>HAVING</b> lọc <b>nhóm</b> sau khi GROUP BY; chỉ giữ lớp có <b>từ 2 học sinh trở lên</b> (12C bị loại).'),21))
S.append(TB(c,B+' · 4','WHERE và HAVING khác nhau thế nào?',['','WHERE','HAVING'],[['Lọc','<b>từng dòng</b>','<b>từng nhóm</b>'],['Thời điểm','<b>trước</b> GROUP BY','<b>sau</b> GROUP BY'],['Dùng hàm tổng hợp','<b>không</b>','<b>có thể</b>'],['Ví dụ','<code>WHERE gioitinh = \'Nu\'</code>','<code>HAVING COUNT(*) &gt;= 2</code>']],note=KEY('Có thể dùng <b>cả hai</b>: WHERE lọc dòng, rồi GROUP BY, rồi HAVING lọc nhóm.')))
S.append(SQ(c,B+' · 4','WHERE + GROUP BY + HAVING + ORDER BY','SELECT lop, COUNT(*) AS so_nu,\n       ROUND(AVG(diemtb),2) AS tb\nFROM hocsinh\nWHERE gioitinh = \'Nu\'\nGROUP BY lop\nHAVING AVG(diemtb) >= 7.5\nORDER BY tb DESC',KEY('Chỉ học sinh <b>nữ</b>; nhóm theo lớp; giữ nhóm <b>TB ≥ 7,5</b>; sắp giảm theo TB.'),20))
S.append(S2(c,B+' · 5','Thứ tự thực hiện câu truy vấn',card('Viết khác với chạy',ul(['<b>1. FROM</b>: lấy bảng.','<b>2. WHERE</b>: lọc dòng.','<b>3. GROUP BY</b>: nhóm.','<b>4. HAVING</b>: lọc nhóm.','<b>5. SELECT</b>: chọn cột, tính biểu thức.','<b>6. ORDER BY</b>: sắp xếp.','<b>7. LIMIT</b>: cắt số dòng.'],6)),KEY('Vì <b>WHERE chạy trước SELECT</b> nên <b>không dùng được bí danh</b> định nghĩa trong SELECT; còn ORDER BY (chạy sau) thì dùng được.')+WARN('Thứ tự <b>viết</b>: SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT.')))
S.append(SQ(c,B+' · 5','Ví dụ: bí danh dùng ở ORDER BY','SELECT hoten, diemtb * 10 AS d100\nFROM hocsinh\nORDER BY d100 DESC\nLIMIT 2',KEY('<code>d100</code> dùng được trong <b>ORDER BY</b> vì ORDER BY chạy sau SELECT; trong WHERE thì <b>không</b>.'),22))
S.append(SQ(c,B+' · 5','Thêm, sửa, xoá dữ liệu (DML)','UPDATE hocsinh SET diemtb = diemtb + 0.5 WHERE lop = \'12C\'',KEY('<b>INSERT INTO</b> bảng VALUES (…); <b>UPDATE</b> bảng SET cột = giá_trị WHERE …; <b>DELETE FROM</b> bảng WHERE …. <b>Quên WHERE</b> sẽ tác động <b>mọi dòng</b>!'),20))
S+=END(c,B,['Thứ tự viết: <b>SELECT – FROM – WHERE – GROUP BY – HAVING – ORDER BY – LIMIT</b>.','<b>WHERE</b> lọc <b>dòng</b>; <b>HAVING</b> lọc <b>nhóm</b> (có hàm tổng hợp).','<b>COUNT, SUM, AVG, MIN, MAX</b>; AVG, SUM bỏ NULL; COUNT(*) đếm cả NULL.','Cột trong SELECT không nằm trong hàm tổng hợp phải có trong <b>GROUP BY</b>.','<b>LIKE</b>: % nhiều kí tự, _ một kí tự; <b>BETWEEN</b> gồm hai đầu.'],[('Lọc dòng','WHERE'),('Lọc nhóm','HAVING'),('Giảm dần','ORDER BY … DESC'),('Loại trùng','DISTINCT')],'Dùng hàm tổng hợp trong WHERE là sai; dùng HAVING.',['<code>COUNT(cột)</code> khác <code>COUNT(*)</code> khi có NULL.','<code>= NULL</code> luôn không đúng; dùng <code>IS NULL</code>.','Chuỗi so sánh <code>LIKE</code> không phân biệt hoa/thường tuỳ hệ.','<code>ORDER BY</code> nên đi kèm <code>LIMIT</code> khi lấy “top n”.'],['<code>CASE WHEN … THEN … END</code>: rẽ nhánh trong SQL.','<b>Hàm cửa sổ</b> (RANK, ROW_NUMBER).','<code>UNION</code>, <code>INTERSECT</code>, <code>EXCEPT</code>.'],
 [('Viết truy vấn liệt kê họ tên các học sinh lớp 12B.',),('Viết truy vấn cho biết điểm trung bình toàn trường.',),('Viết truy vấn đếm số học sinh mỗi giới tính.',),('Viết truy vấn liệt kê các lớp có điểm trung bình trên 7,5.',),('Phân biệt WHERE và HAVING.',)],
 [('<code>SELECT hoten FROM hocsinh WHERE lop = \'12B\';</code> → '+SQL1("SELECT hoten FROM hocsinh WHERE lop='12B'"),),('<code>SELECT AVG(diemtb) FROM hocsinh;</code> → '+SQL1('SELECT ROUND(AVG(diemtb),2) FROM hocsinh'),),('<code>SELECT gioitinh, COUNT(*) FROM hocsinh GROUP BY gioitinh;</code>',),('<code>SELECT lop FROM hocsinh GROUP BY lop HAVING AVG(diemtb) &gt; 7.5;</code>',),('WHERE lọc <b>dòng</b> trước nhóm, không dùng hàm tổng hợp; HAVING lọc <b>nhóm</b> sau GROUP BY.',)],
 [('Viết truy vấn tên và điểm của 2 học sinh nữ điểm cao nhất.',),('Viết truy vấn đếm số học sinh có tên bắt đầu bằng chữ cái bất kì giữa A–D.',),('Cho kết quả truy vấn: <code>SELECT lop, MAX(diemtb) FROM hocsinh GROUP BY lop</code>.',),('Tìm lỗi: <code>SELECT lop, hoten, AVG(diemtb) FROM hocsinh GROUP BY lop</code>.',),('Vì sao <code>SELECT hoten FROM hocsinh WHERE AVG(diemtb) &gt; 7</code> sai? Sửa thế nào để lấy học sinh điểm cao hơn trung bình?',),('Điểm trung bình mỗi lớp (làm tròn 1 số lẻ), chỉ lớp có ít nhất 2 học sinh, sắp giảm.',)],
 [('<code>SELECT hoten, diemtb FROM hocsinh WHERE gioitinh=\'Nu\' ORDER BY diemtb DESC LIMIT 2;</code> → '+SQL1("SELECT hoten, diemtb FROM hocsinh WHERE gioitinh='Nu' ORDER BY diemtb DESC LIMIT 2"),),('<code>… WHERE substr(hoten,1,1) BETWEEN \'A\' AND \'D\'</code> → '+SQL1("SELECT COUNT(*) FROM hocsinh WHERE substr(hoten,1,1) BETWEEN 'A' AND 'D'")+' (An, Binh, Chi, Dung)',),('Mỗi lớp một dòng: '+SQL1('SELECT lop, MAX(diemtb) FROM hocsinh GROUP BY lop')+' (lớp, điểm cao nhất).',),('<b>hoten</b> không có trong GROUP BY và không nằm trong hàm tổng hợp: lỗi (hoặc kết quả không xác định). Phải bỏ hoten hoặc thêm vào GROUP BY.',),('Hàm tổng hợp <b>không dùng trong WHERE</b>. Dùng truy vấn con: <code>WHERE diemtb &gt; (SELECT AVG(diemtb) FROM hocsinh)</code> (xem bài SQL 4).',),('<code>SELECT lop, ROUND(AVG(diemtb),1) tb FROM hocsinh GROUP BY lop HAVING COUNT(*)&gt;=2 ORDER BY tb DESC</code> → '+SQL1("SELECT lop, ROUND(AVG(diemtb),1) AS tb FROM hocsinh GROUP BY lop HAVING COUNT(*)>=2 ORDER BY tb DESC"),)],hper=2)
mkdeck('c3.html','CSDL 3 · SQL truy vấn và nhóm',S)
